INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('flug-graz-wien-aua-eingestellt-alternativen-airail','Flug Graz Wien: AUA stellt Strecke ein – das sind die Alternativen','Austrian Airlines hat die Verbindung Graz–Wien nach mehr als sechs Jahrzehnten eingestellt. Welche Alternativen Reisende jetzt haben – von AIRail bis zum Umstieg in München.','Der **Flug Graz Wien** ist Geschichte: Austrian Airlines hat am Freitag, 23. Oktober 2026, die Inlandsverbindung zwischen der steirischen Landeshauptstadt und dem Flughafen Wien-Schwechat eingestellt. Als letzte planmäßige Maschine war der Kurs OS118 um 16:15 Uhr ab Graz angesetzt. Ab Samstag gibt es keine direkten Flüge mehr zwischen den beiden Flughäfen.

## Warum die AUA den Flug Graz Wien streicht

Die Strecke wurde mehr als sechzig Jahre lang bedient, zu Spitzenzeiten viermal am Tag. Zuletzt nutzten sie rund 130.000 Passagiere pro Jahr. Laut ORF Steiermark flogen jedoch etwa 98 Prozent der Reisenden nur deshalb nach Wien, um dort in einen internationalen Anschlussflug umzusteigen. Die Kurzstrecke schrieb seit Jahren Verluste, die Buchungen gingen weiter zurück. Die Lufthansa-Gruppe, zu der die AUA gehört, zieht die Einstellung daher früher durch als ursprünglich vorgesehen – geplant war das Aus laut ORF erst für 2030. Angekündigt wurde der Schritt bereits im August.

Auch die Abgabenlage spielt bei Kurzstrecken eine Rolle: Für Flüge unter 350 Kilometern sind in Österreich 30 Euro Flugabgabe pro Passagier fällig, sonst 12 Euro.

## Mit Zug und Flug: AIRail zum Flughafen Wien

Wer weiterhin über Wien in die Welt fliegen will, kann auf AIRail zurückgreifen, ein gemeinsames Angebot von ÖBB und AUA mit einem durchgehenden Ticket für Bahn und Flug. Nach Angaben der ÖBB gibt es täglich sieben Verbindungen je Richtung zwischen Klagenfurt, Graz und dem Flughafen Wien. Die wichtigsten Punkte im Überblick:

- Fahrzeit ab Graz: ab rund 2 Stunden 57 Minuten
- Letzter Zug vom Flughafen Wien nach Graz: 23:02 Uhr
- Check-in im ÖBB-Reisezentrum am Grazer Hauptbahnhof, das Gepäck wird erst in Wien aufgegeben
- Gegen Aufpreis kann das Gepäck in Graz zu Hause oder im Hotel abgeholt werden
- Das Ticket gilt nur für den gebuchten Zug, dafür gibt es eine Anschlussgarantie

Zwischen Wien und Graz verkehren grundsätzlich zwei Fernverkehrszüge pro Stunde, am Vormittag und zur Mittagszeit gibt es aber noch einzelne Lücken im Halbstundentakt. Deutlich schneller soll es mit dem Semmering-Basistunnel werden: Nach dessen geplanter Inbetriebnahme Ende 2029 soll die Bahnfahrt Wien–Graz rund 1 Stunde 50 Minuten dauern, etwa 50 Minuten weniger als heute.

## Umsteigen über München, Frankfurt und Zürich

Als zweite Option setzt die Lufthansa-Gruppe auf ihre anderen Drehkreuze. Im Winterflugplan, der am 25. Oktober beginnt, gibt es ab Graz bis zu 20 Flüge pro Woche nach Frankfurt und bis zu 19 nach München. Laut Land Steiermark werden die Kapazitäten ab November nach Frankfurt um rund ein Viertel und nach München um rund zehn Prozent erhöht. Swiss stockt die Verbindung nach Zürich von fünf auf sieben wöchentliche Flüge auf. Zusätzlich fliegen im Winter unter anderem Eurowings nach Berlin, Düsseldorf und Hamburg sowie British Airways nach London-Gatwick.

Ab 24. Oktober bietet außerdem ein privater steirischer Shuttledienst Fahrten zwischen den Flughäfen Graz und Wien an. Einen fixen Fahrplan gibt es nicht, Abfahrten werden gebündelt und die Preise richten sich nach der Auslastung. Der Betreiber versteht das Angebot ausdrücklich nicht als offiziellen Ersatz für die AUA-Verbindung.

## Was gilt für bereits gebuchte Tickets?

Wer noch einen Flug Graz–Wien für die Zeit ab 24. Oktober gebucht hatte, hat nach der EU-Fluggastrechteverordnung Anspruch auf Erstattung des Ticketpreises oder auf eine Ersatzbeförderung. Weil die Einstellung schon Monate vorher angekündigt wurde, besteht in der Regel kein Anspruch auf eine zusätzliche Ausgleichszahlung.

Die steirische Wirtschaftskammer und die Industriellenvereinigung sehen im Wegfall der Verbindung einen Nachteil für den Standort und drängen auf einen Ausbau der verbliebenen Strecken. Der Flughafen Graz gibt sich trotz des Einschnitts zuversichtlich. Eine weitere Verbesserung kommt mit dem Fahrplanwechsel am 13. Dezember: Dann halten laut ÖBB auch die Interregio-Züge zwischen Graz und Maribor am Flughafen Graz.','lifestyle','Mobilität','steiermark','news','Presseinfo Redaktion','/assets/img/artikel/flug-graz-wien-aua-eingestellt-alternativen-airail.webp','news.at (mit Angaben von Austrian Airlines, ÖBB und Land Steiermark)','https://www.news.at/ausflugsziele/aua-graz-wien-letzter-flug-alternativen','published','2026-10-23T16:50:00.000Z','2026-10-23T16:44:49.908Z','Flug Graz Wien eingestellt: Alle Alternativen','Flug Graz Wien: Die AUA hat die Strecke am 23. Oktober eingestellt. So kommen Sie jetzt per AIRail, Umsteigeflug oder Shuttle zum Flughafen Wien.','Flug Graz Wien','["Flug Graz Wien","AUA Graz Wien eingestellt","letzter Flug Graz Wien","AIRail Graz Flughafen Wien","Zug Graz Flughafen Wien","Flughafen Graz Winterflugplan 2026","Graz Wien Alternativen","Semmering-Basistunnel Fahrzeit"]','Flug Graz Wien eingestellt: Zug statt Flugzeug zwischen Graz und dem Flughafen Wien','A modern Austrian Railjet-style red passenger train crossing a green Styrian hilly landscape in autumn at dusk, a small regional airport runway with a parked turboprop aircraft in the far background, soft golden light, Austrian countryside, no text, no logos, no readable signs, no people','[{"q":"Wann war der letzte Flug Graz–Wien?","a":"Austrian Airlines hat die Verbindung am Freitag, 23. Oktober 2026, eingestellt. Ab 24. Oktober gibt es keine direkten Flüge mehr zwischen Graz und Wien."},{"q":"Wie komme ich jetzt von Graz zum Flughafen Wien?","a":"Mit AIRail von ÖBB und AUA: Laut ÖBB gibt es täglich sieben Verbindungen je Richtung, die Fahrzeit ab Graz beträgt ab rund 2 Stunden 57 Minuten."},{"q":"Bekomme ich mein Geld für einen gebuchten Flug zurück?","a":"Ja, für Flüge ab 24. Oktober besteht Anspruch auf Erstattung oder Ersatzbeförderung. Eine zusätzliche Ausgleichszahlung gibt es wegen der frühen Ankündigung in der Regel nicht."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
